css:
.print-format {
	page-width: 54mm;
	page-height: 85.6mm;
	margin-top: 0mm;
	margin-bottom: 0mm;
	margin-left: 0mm;
	margin-right: 0mm;
	padding: 0;
	width: 54mm;
	max-width: 54mm;
	min-height: 0;
}

.print-format .afm-idc {
	position: relative;
	width: 54mm;
	height: 85.6mm;
	overflow: hidden;
	color: #00844E;
	font-family: "Tajawal", "Montserrat", sans-serif;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

.print-format .afm-idc-art {
	position: absolute;
	top: 0;
	left: 0;
	width: 54mm;
	height: 85.6mm;
}

.print-format .afm-idc-photo {
	position: absolute;
	top: 20.8mm;
	left: 16.28mm;
	width: 21mm;
	height: 21mm;
	border-radius: 50%;
	background-color: #F8F5EE;
	border: 0.4mm solid #00844E;
	box-sizing: border-box;
}

.print-format .afm-idc-body {
	position: absolute;
	top: 47.5mm;
	left: 4.42mm;
	display: table;
	width: 45.16mm;
	height: 23.9mm;
}

.print-format .afm-idc-middle {
	display: table-cell;
	vertical-align: middle;
}

.print-format .afm-idc-name,
.print-format .afm-idc-role {
	text-align: center;
	font-size: 6.4pt;
	line-height: 3.16mm;
	font-weight: 600;
}

.print-format .afm-idc-rows {
	margin: 1.98mm 0 0 11.49mm;
	font-size: 4.5pt;
	font-weight: 500;
}

.print-format .afm-idc-row {
	line-height: 2.4mm;
	white-space: nowrap;
}

.print-format .afm-idc-row span {
	display: inline-block;
	vertical-align: top;
}

.print-format .afm-idc-label {
	width: 7.34mm;
}

.print-format .afm-idc-colon {
	width: 1.12mm;
}

.print-format .afm-idc-value {
	max-width: 25.5mm;
	white-space: normal;
	word-break: break-all;
}

.print-format .afm-idc-tag {
	position: absolute;
	top: 74.45mm;
	left: 27.84mm;
	font-family: "Tajawal", "Montserrat", sans-serif;
	font-size: 6.96pt;
	line-height: 4.07mm;
	font-weight: 500;
	letter-spacing: 0.25em;
	color: #111915;
}
